import{_ as s,o as t,c as n,a0 as i}from"./chunks/framework.DQOulFGV.js";const c=JSON.parse('{"title":"Kafka 消费者组与 Rebalance","description":"","frontmatter":{"doc_id":"kafka-消费者组与Rebalance","title":"Kafka 消费者组与 Rebalance"},"headers":[],"relativePath":"kafka/04-消费者组与Rebalance.md","filePath":"kafka/04-消费者组与Rebalance.md"}'),e={name:"kafka/04-消费者组与Rebalance.md"};function l(p,a,r,h,d,o){return t(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="kafka-消费者组与-rebalance" tabindex="-1">Kafka 消费者组与 Rebalance <a class="header-anchor" href="#kafka-消费者组与-rebalance" aria-label="Permalink to &quot;Kafka 消费者组与 Rebalance&quot;">​</a></h1><hr><h2 id="_1-rebalance-触发条件" tabindex="-1">1. Rebalance 触发条件 <a class="header-anchor" href="#_1-rebalance-触发条件" aria-label="Permalink to &quot;1. Rebalance 触发条件&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R[&quot;触发 Rebalance(分区重新分配)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R --&gt; A[&quot;消费者加入组&lt;br&gt;(新实例启动)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R --&gt; B[&quot;消费者离开组&lt;br&gt;(实例下线/崩溃)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R --&gt; C[&quot;消费者心跳超时&lt;br&gt;(session.timeout.ms 内未发心跳)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R --&gt; D[&quot;Topic 分区数变化&lt;br&gt;(增加分区)&quot;]</span></span></code></pre></div><blockquote><p><strong>Rebalance 的代价</strong>：Rebalance 期间，<strong>整个消费者组停止消费</strong>，直到重新分配完成。频繁 Rebalance 会导致消费停顿，是 Kafka 性能问题的常见原因。</p></blockquote><hr><h2 id="_2-三种分区分配策略" tabindex="-1">2. 三种分区分配策略 <a class="header-anchor" href="#_2-三种分区分配策略" aria-label="Permalink to &quot;2. 三种分区分配策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>分配方式</th><th>优点</th><th>缺点</th><th>为什么选它</th></tr></thead><tbody><tr><td><strong>Range</strong></td><td>按分区范围分配给消费者</td><td>简单</td><td>分配不均匀（前几个消费者分到更多）</td><td>简单场景</td></tr><tr><td><strong>RoundRobin</strong></td><td>轮询分配所有分区</td><td>均匀</td><td>Rebalance 后变动大</td><td>需要均匀分配时</td></tr><tr><td><strong>Sticky</strong></td><td>尽量保持上次的分配结果</td><td>减少迁移，Rebalance 影响小</td><td>实现复杂</td><td><strong>生产环境推荐</strong></td></tr></tbody></table><hr><h2 id="_3-避免频繁-rebalance-的配置" tabindex="-1">3. 避免频繁 Rebalance 的配置 <a class="header-anchor" href="#_3-避免频繁-rebalance-的配置" aria-label="Permalink to &quot;3. 避免频繁 Rebalance 的配置&quot;">​</a></h2><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 消费者心跳间隔（建议为 session.timeout.ms 的 1/3）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 为什么是 1/3：保证在超时前至少发送 3 次心跳，容忍 2 次失败</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">heartbeat.interval.ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 会话超时时间（消费者超过此时间未发心跳则被踢出）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">session.timeout.ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=10000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 消费者两次 poll 的最大间隔（处理时间过长会触发 Rebalance）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 如果业务处理时间可能超过 5 分钟，需要调大此值</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max.poll.interval.ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=300000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 每次 poll 的最大消息数（减少单次处理时间，避免超过 max.poll.interval.ms）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max.poll.records</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=500</span></span></code></pre></div><hr><h2 id="_4-rebalance-流程" tabindex="-1">4. Rebalance 流程 <a class="header-anchor" href="#_4-rebalance-流程" aria-label="Permalink to &quot;4. Rebalance 流程&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C1 as Consumer 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C2 as Consumer 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant GC as Group Coordinator</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C1-&gt;&gt;GC: 发送 JoinGroup 请求</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C2-&gt;&gt;GC: 发送 JoinGroup 请求</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GC--&gt;&gt;C1: 选为 Group Leader，返回成员列表</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GC--&gt;&gt;C2: 返回 JoinGroup 响应</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C1-&gt;&gt;GC: 发送 SyncGroup（携带分配方案）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C2-&gt;&gt;GC: 发送 SyncGroup</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GC--&gt;&gt;C1: 返回分配结果（消费 P0、P1）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GC--&gt;&gt;C2: 返回分配结果（消费 P2）</span></span></code></pre></div><blockquote><p><strong>注意</strong>：Rebalance 期间所有消费者停止消费，等待分配完成后才继续。</p></blockquote><hr><h2 id="_5-最佳实践" tabindex="-1">5. 最佳实践 <a class="header-anchor" href="#_5-最佳实践" aria-label="Permalink to &quot;5. 最佳实践&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>消费者处理时间长</td><td>调大 <code>max.poll.interval.ms</code>，减小 <code>max.poll.records</code></td></tr><tr><td>消费者频繁重启</td><td>检查应用稳定性，避免频繁触发 Rebalance</td></tr><tr><td>需要减少 Rebalance 影响</td><td>使用 <strong>Sticky</strong> 分配策略</td></tr><tr><td>分区数规划</td><td>分区数 ≥ 消费者数，避免消费者空闲</td></tr></tbody></table>`,18)])])}const g=s(e,[["render",l]]);export{c as __pageData,g as default};
